+	map = bpf_map_get(addr_space_cast_result_map_fd);
+	if (IS_ERR(map)) {
+		err = PTR_ERR(map);
+		pr_info("ADDR_SPACE_CAST: result map get failed err=%d\n", err);
+		return err;
+	}
