+	rcu_read_lock();
+	ptr = map->ops->map_lookup_elem(map, &key);
+	if (IS_ERR(ptr))
+		err = PTR_ERR(ptr);
+	else if (!ptr)
+		err = -ENOENT;
+	else
+		value = READ_ONCE(*(u32 *)ptr);
+	rcu_read_unlock();
+	bpf_map_put(map);
+
+	if (err) {
+		pr_info("ADDR_SPACE_CAST: result map lookup failed err=%d\n",
+			err);
+		return err;
+	}
