+pub trait IoCopyable: IoBackend {
+    /// Copy contents of `view` to `buffer`.
+    ///
+    /// # Safety
+    ///
+    /// - `buffer` is valid for volatile write for `view.size()` bytes.
+    unsafe fn copy_from_io(view: Self::View<'_, [u8]>, buffer: *mut u8);
